import { SIDE_COLORS, type SideColor } from "./cube.ts";

export type CaseId = string;

export interface PllCase {
  /** Name shown on the answer button, e.g. "G". */
  id: CaseId;
  /** Recognition group the case is listed under. */
  group: string;
  /** PLL variants whose pictures count as this answer. Letter families (G, J, R, N, A, U) pool all of theirs. */
  files: string[];
  /** What you type to answer. */
  alias: string;
}

/** Every variant has a picture for each color rotation × angle, generated by scripts/generate-cubes.ts. */
export const ANGLES = 4;
export const COLORS: readonly SideColor[] = SIDE_COLORS;

const GROUPS: { label: string; cases: [CaseId, string | string[]][] }[] = [
  { label: "Edges only", cases: [["H", "H"], ["Z", "Z"], ["U", ["Ua", "Ub"]]] },
  { label: "Corners only", cases: [["A", ["Aa", "Ab"]], ["E", "E"]] },
  {
    label: "Adjacent corner swap",
    cases: [["T", "T"], ["F", "F"], ["J", ["Ja", "Jb"]], ["R", ["Ra", "Rb"]], ["G", ["Ga", "Gb", "Gc", "Gd"]]],
  },
  { label: "Diagonal corner swap", cases: [["V", "V"], ["Y", "Y"], ["N", ["Na", "Nb"]]] },
];

export const GROUP_LABELS = GROUPS.map((g) => g.label);

export const CASES: PllCase[] = GROUPS.flatMap((g) =>
  g.cases.map(([id, file]) => ({
    id,
    group: g.label,
    files: ([] as string[]).concat(file),
    alias: id.toLowerCase(),
  })),
);

export const BY_ID: Record<CaseId, PllCase> = Object.fromEntries(CASES.map((c) => [c.id, c]));

/** Every case is drilled by default. */
export const DEFAULT_ENABLED: CaseId[] = CASES.map((c) => c.id);

export function imageUrl(variant: string, color: SideColor, angle: number): string {
  return `${import.meta.env.BASE_URL}cubes/${variant}-${color}-${angle}.svg`;
}
